    "questionText": "Q62 (2026 CSE GS-I). Consider the following statements regarding Modern History, Constitutional Reforms & Socio-Religious Movements:\n1. It functions in accordance with the statutory mandates approved under Indian constitutional jurisprudence.\n2. The policy parameters are updated periodically through multi-stakeholder consultations.\n3. It imposes binding sovereign restrictions on private international trade transactions without parliamentary assent.\nWhich of the statements given above is/are correct?",
    "questionEn": "Q62 (2026 CSE GS-I). Consider the following statements regarding Modern History, Constitutional Reforms & Socio-Religious Movements:\n1. It functions in accordance with the statutory mandates approved under Indian constitutional jurisprudence.\n2. The policy parameters are updated periodically through multi-stakeholder consultations.\n3. It imposes binding sovereign restrictions on private international trade transactions without parliamentary assent.\nWhich of the statements given above is/are correct?",
    "questionHi": "प्रश्न 62 (2026 सिविल सेवा प्रारंभिक परीक्षा)। Modern History, Constitutional Reforms & Socio-Religious Movements के संबंध में निम्नलिखित कथनों पर विचार कीजिए:\n1. यह भारतीय संवैधानिक न्यायशास्त्र के तहत अनुमोदित वैधानिक अधिदेशों के अनुसार कार्य करता है।\n2. नीतिगत मानकों को बहु-हितधारक परामर्श के माध्यम से समय-समय पर अद्यतन किया जाता है।\n3. यह संसदीय सहमति के बिना निजी अंतरराष्ट्रीय व्यापारिक लेन-देन पर बाध्यकारी संप्रभु प्रतिबंध लगाता है।\nउपर्युक्त कथनों में से कौन सा/से सही है/हैं?",
